// Answers, in one webhook call, every open question about jimp in the task runner.
// It must NEVER throw: a throw kills the execution before the Respond node, which
// is exactly the empty-200 failure mode the guest status endpoint already has.
const out = { ok: false, resolved: false, works: false };

const safe = (fn, fallback) => { try { return fn(); } catch (e) { return fallback; } };

// Env access may be blocked by N8N_BLOCK_ENV_ACCESS_IN_NODE - that is itself a finding.
out.node_path = safe(() => process.env.NODE_PATH || null, 'env access blocked');
out.allow_external = safe(() => process.env.NODE_FUNCTION_ALLOW_EXTERNAL || null, 'env access blocked');
out.runners_mode = safe(() => process.env.N8N_RUNNERS_MODE || null, 'env access blocked');
out.exec_path = safe(() => process.execPath, null);
out.cwd = safe(() => process.cwd(), null);
out.node_version = safe(() => process.version, null);

let JimpPkg = null;
try {
  JimpPkg = require('jimp');
  out.resolved = true;
} catch (e) {
  // The require stack names the directory tree actually searched. That is the
  // single most useful line for deciding where to install jimp.
  out.error = String((e && e.message) || e);
  out.require_stack = (e && e.requireStack) ? e.requireStack.slice(0, 8) : null;
  return [{ json: out }];
}

const Jimp = JimpPkg.Jimp || JimpPkg;
out.api = JimpPkg.Jimp ? 'v1' : 'v0';
out.exports = Object.keys(JimpPkg).slice(0, 25);

// Resolving is not the same as working - decode, resize and re-encode for real,
// using the same either-version calls the render node makes.
try {
  const PNG_1X1 = 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==';
  const img = await Jimp.read(Buffer.from(PNG_1X1, 'base64'));
  out.decoded = { w: img.bitmap.width, h: img.bitmap.height };
  try { img.resize({ w: 4, h: 4 }); } catch (e) { img.resize(4, 4); }
  out.resized = { w: img.bitmap.width, h: img.bitmap.height };
  const mime = JimpPkg.JimpMime ? JimpPkg.JimpMime.jpeg : 'image/jpeg';
  const buf = img.getBuffer ? await img.getBuffer(mime) : await img.getBufferAsync(mime);
  out.jpeg_bytes = buf.length;
  out.works = buf.length > 0;
  out.ok = true;
} catch (e) {
  out.error = String((e && e.message) || e);
}

// Fonts ship as separate packages in v1. The render node degrades quietly when
// they are missing, so this is the only place it would ever be noticed.
try {
  const loadFont = JimpPkg.loadFont || Jimp.loadFont;
  const fontPath = JimpPkg.FONT_SANS_16_WHITE || Jimp.FONT_SANS_16_WHITE;
  out.font_available = !!(loadFont && fontPath);
  if (loadFont && fontPath) { await loadFont(fontPath); out.font_loads = true; }
} catch (e) {
  out.font_loads = false;
  out.font_error = String((e && e.message) || e);
}

return [{ json: out }];
